/**
 * 연합운동 찾기: 10 expressions in a row (rest + 9), then a map of which
 * face regions move involuntarily on the affected side during which
 * expression, with the exercises aimed at each finding.
 */
import { useEffect, useRef, useState } from 'preact/hooks';
import {
  AGGREGATION,
  COUPLING_EXPRESSIONS,
  COUPLING_REGIONS,
  analyzeCoupling,
  type CouplingExpression,
  type CouplingResult,
  type FrameObservation,
  type FrameQuality,
  type QualityIssue,
} from '../../core';
import { FEATURES } from '../../config';
import { createSynkRecord } from '../../data/records';
import { actions, useApp } from '../../data/store';
import { exerciseById } from '../../rehab/exercises';
import { AppBar, Notice } from '../components/common';
import { Icon } from '../icons';
import { ISSUE_LABEL, SIDE_LABEL, dayLabel, fmtDate } from '../labels';
import { navigate } from '../router';
import { FOR_REGION, FaceMapCard, HOW, LABEL, REGION, REGION_SUBJ, WHEN, describe } from '../synk';
import { CaptureTracker, type Grabbed } from '../../vision/captureTracker';
import { CameraStage, speak, useFaceCamera, useWakeLock } from '../useFaceCamera';
import { AlgoTag } from '../components/AlgoTag';

type Step = 'rest' | CouplingExpression;
const QUEUE: readonly Step[] = ['rest', ...COUPLING_EXPRESSIONS];

const RECORD_MS = 3000;
const MAX_AUTO_REPEAT = 2;

type Phase =
  | { k: 'intro' }
  | { k: 'align' }
  | { k: 'countdown'; i: number; n: number; note?: string }
  | { k: 'record'; i: number; start: number }
  | { k: 'relax'; i: number }
  | { k: 'result'; r: CouplingResult; demo?: boolean; savedId?: string };

/** Example result on a synthetic face with oral–ocular synkinesis (demo builds; no camera needed). */
async function demoResult(affectedSide: 'left' | 'right'): Promise<CouplingResult> {
  const { syntheticSession } = await import('../../core/synthetic');
  const s = syntheticSession({ affectedSide, strength: 0.8, droop: 0, synkinesis: 0.9, drag: 0 }, { seed: 7 });
  const src: Record<CouplingExpression, keyof typeof s.tasks> = {
    brow: 'brow',
    eyeGentle: 'eyeClose',
    eyeTight: 'eyeClose',
    smileClosed: 'smile',
    pucker: 'pucker',
    oh: 'pucker',
    oo: 'pucker',
    frown: 'snarl',
    ee: 'smile',
  };
  return analyzeCoupling({
    affectedSide,
    rest: s.rest,
    expressions: Object.fromEntries(COUPLING_EXPRESSIONS.map((e) => [e, s.tasks[src[e]] ?? []])),
  });
}

/** Findings that are new / gone compared with an earlier result. */
function diffFindings(cur: CouplingResult, prev: CouplingResult) {
  const key = (f: { expression: string; region: string }) => `${f.expression}|${f.region}`;
  const was = new Set(prev.findings.map(key));
  const now = new Set(cur.findings.map(key));
  return {
    added: cur.findings.filter((f) => !was.has(key(f))),
    gone: prev.findings.filter((f) => !now.has(key(f)) && cur.cells[f.expression]),
  };
}

export function SynkFinder({ id }: { id?: string }) {
  const { profile, synk, integrity } = useApp();
  const stored = id ? synk.find((x) => x.id === id) : undefined;
  const [phase, setPhase] = useState<Phase>(stored ? { k: 'result', r: stored.result, savedId: stored.id } : { k: 'intro' });
  const [saving, setSaving] = useState(false);
  const [progress, setProgress] = useState(0);
  const frames = useRef<Partial<Record<Step, FrameObservation[]>>>({});
  const rec = useRef<{
    step: Step;
    frames: FrameObservation[];
    grabbed: Grabbed[];
    valid: number;
    issues: Partial<Record<QualityIssue, number>>;
  } | null>(null);
  const tracker = useRef(new CaptureTracker());
  const stableSince = useRef<number | null>(null);
  const repeats = useRef(0);
  const voice = profile?.voiceGuide ?? true;
  const cameraOn = phase.k !== 'intro' && phase.k !== 'result';

  const cam = useFaceCamera(cameraOn, (obs: FrameObservation, q: FrameQuality, src: HTMLVideoElement) => {
    if (rec.current) {
      rec.current.frames.push(obs);
      if (q.ok) {
        rec.current.valid++;
        // Tracked from the first valid rest frame (FPA-SYNK 0.2.0, as FPA-GEOM 0.3.0); detections are the fallback.
        const tk = tracker.current;
        if (rec.current.step === 'rest' && !tk.ref) tk.setRef(src, obs);
        const gray = tk.grab(src, obs);
        if (gray) rec.current.grabbed.push({ obs, gray });
      }
      for (const i of q.issues) rec.current.issues[i] = (rec.current.issues[i] ?? 0) + 1;
    }
    stableSince.current = q.ok ? (stableSince.current ?? performance.now()) : null;
  });
  useWakeLock(cameraOn);

  useEffect(() => {
    if (phase.k !== 'align' || cam.status !== 'ready') return;
    speak('얼굴을 화면 가운데에 맞추고 정면을 바라보세요.', voice);
    const id = setInterval(() => {
      const s = stableSince.current;
      setProgress(s ? Math.min(1, (performance.now() - s) / 1500) : 0);
      if (s && performance.now() - s >= 1500) {
        clearInterval(id);
        setPhase({ k: 'countdown', i: 0, n: 3 });
      }
    }, 100);
    return () => clearInterval(id);
  }, [phase.k, cam.status]);

  useEffect(() => {
    if (phase.k === 'countdown') {
      if (phase.n === 3) speak(`${LABEL[QUEUE[phase.i]!]}. ${HOW[QUEUE[phase.i]!]}`, voice);
      const id = setTimeout(() => {
        if (phase.n > 1) setPhase({ ...phase, n: phase.n - 1 });
        else {
          if (QUEUE[phase.i] === 'rest') tracker.current.reset();
          rec.current = { step: QUEUE[phase.i]!, frames: [], grabbed: [], valid: 0, issues: {} };
          setPhase({ k: 'record', i: phase.i, start: performance.now() });
        }
      }, 1000);
      return () => clearTimeout(id);
    }
    if (phase.k === 'record') {
      const id = setInterval(() => {
        const p = (performance.now() - phase.start) / RECORD_MS;
        setProgress(Math.min(1, p));
        if (p < 1) return;
        clearInterval(id);
        const r = rec.current!;
        rec.current = null;
        if (r.valid < AGGREGATION.minValidFrames.video && repeats.current < MAX_AUTO_REPEAT) {
          repeats.current++;
          const top = Object.entries(r.issues).sort((a, b) => (b[1] ?? 0) - (a[1] ?? 0))[0];
          speak('다시 한 번 하겠습니다.', voice);
          setPhase({ k: 'countdown', i: phase.i, n: 3, note: top ? ISSUE_LABEL[top[0] as QualityIssue] : '얼굴이 잘 보이지 않았어요' });
          return;
        }
        repeats.current = 0;
        try {
          const tk = tracker.current;
          frames.current[QUEUE[phase.i]!] =
            r.step === 'rest' && tk.ref ? [tk.ref.obs, ...tk.trackEven(r.frames, r.grabbed)] : tk.trackEven(r.frames, r.grabbed);
        } catch (e) {
          console.warn('tracking failed, using detections', e);
          frames.current[QUEUE[phase.i]!] = r.frames;
        }
        if (phase.i > 0) speak('힘을 빼세요.', voice);
        setPhase({ k: 'relax', i: phase.i });
      }, 50);
      return () => clearInterval(id);
    }
    if (phase.k === 'relax') {
      const id = setTimeout(() => {
        if (phase.i + 1 < QUEUE.length) setPhase({ k: 'countdown', i: phase.i + 1, n: 3 });
        else {
          const f = frames.current;
          const r = analyzeCoupling({
            affectedSide: profile!.affectedSide,
            rest: f.rest ?? [],
            expressions: Object.fromEntries(COUPLING_EXPRESSIONS.map((e) => [e, f[e] ?? []])),
          });
          speak(
            r.findings.length ? `함께 움직이는 곳이 ${r.findings.length}군데 있습니다.` : '뚜렷한 연합운동은 보이지 않았습니다.',
            voice,
          );
          setPhase({ k: 'result', r });
        }
      }, 1300);
      return () => clearTimeout(id);
    }
    return undefined;
  }, [phase]);

  if (!profile) return null;

  if (phase.k === 'intro') {
    return (
      <>
        <AppBar title="연합운동 찾기" sub="약 1분 30초 · 10가지 표정" onBack />
        <main class="main">
          <div class="card">
            <h2>어디가 함께 움직이는지 찾아봅니다</h2>
            <p class="small ink2">
              회복 중에 입을 움직이면 눈이 작아지거나, 눈을 감으면 입꼬리가 따라 올라가는 <b>연합운동(동반운동)</b>이 생길 수 있습니다.
              10가지 표정을 차례로 지으면, 표정마다 의도하지 않은 곳이 마비 쪽에서 더 움직이는지 비교합니다.
            </p>
            <ol class="small ink2" style={{ margin: 0, paddingLeft: '20px' }}>
              {QUEUE.map((s) => (
                <li>
                  <b>{LABEL[s]}</b> — {HOW[s]}
                </li>
              ))}
            </ol>
          </div>
          <div class="card tight">
            <Notice>
              <span class="small">
                밝은 곳에서 안경을 벗고, 휴대폰을 눈높이에 고정하세요. 영상은 저장되지 않습니다. 이 결과는 참고용이며 진단이 아닙니다.
              </span>
            </Notice>
          </div>
          <button class="btn primary block" onClick={() => setPhase({ k: 'align' })}>
            <Icon name="camera" /> 카메라 켜고 시작
          </button>
          {synk.length > 0 && (
            <div class="card tight">
              <div class="card-head">
                <h3>지난 기록</h3>
                <span class="xsmall muted">{synk.length}회</span>
              </div>
              <div class="list">
                {[...synk].reverse().map((x) => (
                  <a class="list-item" href={`#/synk/${x.id}`}>
                    <div class="grow">
                      <div style={{ fontWeight: 600 }}>
                        {fmtDate(x.createdAt)} · {dayLabel(x.daysSinceOnset)}
                      </div>
                      <div class="xsmall ink2">
                        {x.result.findings.length ? `함께 움직이는 곳 ${x.result.findings.length}군데` : '뚜렷한 연합운동 없음'}
                        {x.result.status === 'incomplete' ? ' · 일부 표정 미측정' : ''}
                      </div>
                    </div>
                    <Icon name="chev" class="chev" />
                  </a>
                ))}
              </div>
            </div>
          )}
          {FEATURES.demo && (
            <button
              class="btn ghost block"
              onClick={async () => setPhase({ k: 'result', r: await demoResult(profile.affectedSide), demo: true })}
            >
              예시 결과 보기 (합성 얼굴)
            </button>
          )}
        </main>
      </>
    );
  }

  if (phase.k === 'result') {
    const r = phase.r;
    const mild = r.mild ?? [];
    const regions = [...new Set([...r.findings, ...mild].map((f) => f.region))];
    const savedAt = phase.savedId ? synk.find((x) => x.id === phase.savedId)?.createdAt : undefined;
    // Previous saved result: the one before this record, or the latest one for a new result.
    const prev = [...synk].reverse().find((x) => x.id !== phase.savedId && (!savedAt || x.createdAt < savedAt));
    const diff = prev && !phase.demo ? diffFindings(r, prev.result) : null;
    const save = async () => {
      setSaving(true);
      const rec = await createSynkRecord({ result: r, profile, engine: cam.engine()?.info ?? null, camera: cam.cameraLabel() });
      await actions.addSynk(rec);
      setSaving(false);
      setPhase({ ...phase, savedId: rec.id });
    };
    return (
      <>
        <AppBar
          title="연합운동 찾기 결과"
          sub={`${savedAt ? `${fmtDate(savedAt)} · ` : ''}마비 쪽 ${SIDE_LABEL[r.affectedSide]}`}
          onBack={() => navigate('/')}
        />
        <main class="main">
          {phase.demo && (
            <div class="card tight">
              <Notice>
                <span class="small">합성 얼굴(입 움직임 때 눈이 함께 작아지는 설정)로 만든 예시 결과입니다. 실제 측정이 아닙니다.</span>
              </Notice>
            </div>
          )}
          {r.status === 'failed' ? (
            <div class="card danger">
              <Notice tone="danger">얼굴이 충분히 보이지 않아 분석하지 못했습니다. 밝은 곳에서 다시 해 주세요.</Notice>
            </div>
          ) : (
            <>
              <div class={`card ${r.findings.length ? 'warn' : 'good'}`}>
                <h3>{r.findings.length ? `함께 움직이는 곳 ${r.findings.length}군데` : '뚜렷한 연합운동이 보이지 않습니다'}</h3>
                {r.findings.length > 0 ? (
                  <ul class="small" style={{ margin: 0, paddingLeft: '18px' }}>
                    {r.findings.slice(0, 6).map((f) => (
                      <li>{describe(r, f.expression, f.region)}.</li>
                    ))}
                  </ul>
                ) : (
                  <p class="small ink2">표정마다 목표가 아닌 곳의 좌우 움직임 차이가 기준보다 작았습니다.</p>
                )}
                {mild.length > 0 && (
                  <>
                    <b class="small">미세하게 함께 움직이는 곳 (의심) {mild.length}군데</b>
                    <ul class="small ink2" style={{ margin: 0, paddingLeft: '18px' }}>
                      {mild.slice(0, 6).map((f) => (
                        <li>{describe(r, f.expression, f.region)}.</li>
                      ))}
                    </ul>
                    <p class="xsmall muted">
                      기준의 절반 이상이면서, 표정을 짓는 동안 마비 쪽에서 함께 커졌다 작아진 움직임입니다. 반복 측정에서 계속 보이는지
                      확인하세요.
                    </p>
                  </>
                )}
                {r.missing.length > 0 && <p class="xsmall muted">측정되지 않은 표정: {r.missing.map((e) => LABEL[e]).join(', ')}</p>}
              </div>

              {diff && prev && (
                <div class="card tight">
                  <b class="small">
                    지난 기록({fmtDate(prev.createdAt)}) {prev.result.findings.length}군데 → 이번 {r.findings.length}군데
                  </b>
                  {diff.gone.length > 0 && (
                    <div class="xsmall ink2">사라진 곳: {diff.gone.map((f) => `${WHEN[f.expression]} ${REGION[f.region]}`).join(', ')}</div>
                  )}
                  {diff.added.length > 0 && (
                    <div class="xsmall ink2">
                      새로 보인 곳: {diff.added.map((f) => `${WHEN[f.expression]} ${REGION[f.region]}`).join(', ')}
                    </div>
                  )}
                </div>
              )}
              <FaceMapCard r={r} />
              <div class="card">
                <h3>표정별 지도</h3>
                <div class="synk-map" role="table" aria-label="표정별 부위 움직임">
                  <div role="row" class="head">
                    <span role="columnheader">표정</span>
                    {COUPLING_REGIONS.map((g) => (
                      <span role="columnheader">{REGION[g]}</span>
                    ))}
                  </div>
                  {COUPLING_EXPRESSIONS.map((e) => (
                    <div role="row">
                      <span role="rowheader">{LABEL[e]}</span>
                      {COUPLING_REGIONS.map((g) => {
                        const c = r.cells[e]?.[g];
                        if (!c)
                          return (
                            <span role="cell" class="na">
                              –
                            </span>
                          );
                        if (c.target)
                          return (
                            <span role="cell" class="target">
                              목표
                            </span>
                          );
                        return (
                          <span role="cell" class={c.flagged ? 'flag' : c.mild ? 'mild' : ''}>
                            {c.flagged ? '함께 움직임' : c.mild ? '미세' : '·'}
                          </span>
                        );
                      })}
                    </div>
                  ))}
                </div>
                <p class="xsmall muted">
                  “목표”는 그 표정에서 원래 움직여야 하는 곳, “함께 움직임”은 마비 쪽이 건강한 쪽보다 기준 이상 더 움직인 곳입니다(눈 10%,
                  윗입술 약 1.5 mm, 그 밖 약 2 mm). “미세”는 기준의 절반 이상이면서 표정과 함께 커졌다 작아진 곳입니다. 알고리즘{' '}
                  <AlgoTag id="FPA-SYNK" version={r.algorithm.version} /> · 임상 검증 전.
                </p>
              </div>

              {regions.length > 0 && (
                <div class="card">
                  <h3>도움이 되는 운동</h3>
                  {regions.map((g) => (
                    <div class="finding">
                      <b>{REGION_SUBJ[g]} 함께 움직일 때</b>
                      <div class="row wrap" style={{ gap: '6px', marginTop: '4px' }}>
                        {FOR_REGION[g]
                          .map((id) => exerciseById(id))
                          .filter((x) => !!x)
                          .map((x) => (
                            <a class="btn sm" href={`#/exercise/${x!.id}`}>
                              {x!.title} <Icon name="chev" />
                            </a>
                          ))}
                      </div>
                    </div>
                  ))}
                  <p class="xsmall muted">
                    연합운동이 있을 때는 강하게 움직이는 연습보다 이완·스트레칭·분리 운동이 우선입니다. 주치의와 상의하세요.
                  </p>
                </div>
              )}
            </>
          )}
          {phase.savedId ? (
            <p class="xsmall muted center">
              <Icon name="shield" /> {integrity[phase.savedId] === false ? '무결성 오류' : '기록에 저장됨 · 무결성 봉인(SHA-256)'}
            </p>
          ) : (
            !phase.demo &&
            r.status !== 'failed' && (
              <button class="btn primary block" onClick={save} disabled={saving}>
                <Icon name="check" /> {saving ? '저장 중…' : '기록으로 저장'}
              </button>
            )
          )}
          <button class="btn block" onClick={() => (id ? navigate('/synk') : setPhase({ k: 'intro' }))}>
            {id ? '새로 찾기' : '다시 하기'}
          </button>
          {phase.demo && <p class="xsmall muted center">예시 결과는 저장되지 않습니다.</p>}
        </main>
      </>
    );
  }

  const i = 'i' in phase ? phase.i : -1;
  const step = i >= 0 ? QUEUE[i]! : null;
  const q = cam.quality;
  return (
    <>
      <AppBar
        title={step ? LABEL[step] : '얼굴 위치 맞추기'}
        sub={step ? `${i + 1} / ${QUEUE.length}` : undefined}
        onBack={() => navigate('/')}
      />
      <main class="main bare">
        <CameraStage cam={cam}>
          <div class="hud">
            <div class="chips">
              {q && q.ok && (
                <span class="chip good">
                  <Icon name="check" /> 좋아요
                </span>
              )}
              {q?.issues.slice(0, 2).map((x) => (
                <span class="chip warn">{ISSUE_LABEL[x]}</span>
              ))}
            </div>
            {phase.k === 'align' && (
              <div class="banner">
                <div class="big">정면을 바라보세요</div>
                <div class="progress">
                  <div style={{ width: `${progress * 100}%` }} />
                </div>
              </div>
            )}
            {(phase.k === 'countdown' || phase.k === 'record' || phase.k === 'relax') && step && (
              <div class="banner">
                <div class="big">{phase.k === 'relax' ? '힘을 빼고 편안히' : phase.k === 'record' ? '지금! 그대로 유지' : LABEL[step]}</div>
                {phase.k === 'countdown' && <div class="small">{phase.note ? `${phase.note} · 다시 진행합니다` : HOW[step]}</div>}
                {phase.k === 'record' && (
                  <div class="progress">
                    <div style={{ width: `${progress * 100}%` }} />
                  </div>
                )}
              </div>
            )}
          </div>
          {phase.k === 'countdown' && <div class="count">{phase.n}</div>}
        </CameraStage>
        <div class="taskdots" aria-hidden="true">
          {QUEUE.map((_, k) => (
            <span class={k < i ? 'done' : k === i ? 'now' : ''} />
          ))}
        </div>
        {step && <p class="center ink2">{HOW[step]}</p>}
      </main>
    </>
  );
}
